        elif method == ""whisper"":
            self.whisper(user, message)
        elif method == ""me"":
            self.me(message)
        elif method == ""reply"":
            if event.type in [""action"", ""pubmsg""]:
                self.say(message)
            elif event.type == ""whisper"":
                self.whisper(user, message)
        else:
