                org_info = """"
                if channel == self.PRIVATE_CHANNEL:
                    if row.org_name:
                        org_info = "", %s of %s"" % (row.org_rank_name, row.org_name)

                blob += "" | %s (%d/<green>%d</green>) %s %s%s%s\n"" % (row.name, row.level or 0, row.ai_level or 0, row.faction, row.profession, afk, org_info)
