    def __new__(cls, arg):
        if isinstance(arg, cls):
            return arg
        if isinstance(arg, basestring):
            return cls._from_name(arg)
        if isinstance(arg, (tuple, list)):
            return cls._from_name(""."".join(arg))
        raise TypeError

    @classmethod
    def _from_name(cls, name):
        self = object.__new__(cls)
        self.name = str(name)
        self.parts = tuple(self.name.split('.'))
        if not is_identifier(self.name, dotted=True):
            raise BadDottedIdentifierError(""Invalid python symbol name %r"" % (name,))
        return self

    @cached_attribute
    def parent(self):
        if len(self.parts) > 1:
            return DottedIdentifier('.'.join(self.parts[:-1]))
        else:
            return None

    @cached_attribute
    def prefixes(self):
        parts = self.parts
        idxes = range(1, len(parts)+1)
        result = ['.'.join(parts[:i]) for i in idxes]
        return tuple(DottedIdentifier(x) for x in result)

    def startswith(self, o):
        o = type(self)(o)
        return self.parts[:len(o.parts)] == o.parts

    def __getitem__(self, x):
        return type(self)(self.parts[x])

    def __len__(self):
        return len(self.parts)

    def __iter__(self):
        return (type(self)(x) for x in self.parts)

    def __add__(self, suffix):
        return type(self)(""%s.%s"") % (self, suffix)

    def __str__(self):
        return self.name

    def __repr__(self):
        return ""%s(%r)"" % (type(self).__name__, self.name)

    def __hash__(self):
        return hash(self.name)

    def __eq__(self, other):
        if self is other:
            return True
        if not isinstance(other, DottedIdentifier):
            return NotImplemented
        return self.name == other.name

    def __ne__(self, other):
        if self is other:
            return False
        if not isinstance(other, DottedIdentifier):
            return NotImplemented
        return self.name != other.name

    def __cmp__(self, other):
        if self is other:
            return 0
        if not isinstance(other, DottedIdentifier):
            return NotImplemented
        return cmp(self.name, other.name)"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",[],[],True,reject,"def exports(self):

