    """"""
    Remove empty values and JSON-LD relics from an input file
    @param inp: JSON-LD representation
    @return: JSON representation
    """"""
    def _is_empty(o) -> bool:
        return o is None or o == [] or o == {}

    if isinstance(inp, list):
        for e in [inpe for inpe in inp if _is_empty(inpe)]:
            del(inp[e])
        for e in inp:
            json_clean(e)
    elif isinstance(inp, dict):
        for k, v in list(inp.items()):
            if k.startswith('@') or _is_empty(v):
                del(inp[k])
            else:
                json_clean(v)
    return inp"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}, {""method_name"": ""load_source"", ""path"": ""linkml_runtime/loaders/loader_root.py"", ""class_name"": null, ""start_line"": 8, ""end_line"": 33, ""source"": ""def load_source(source: Union[str, dict, TextIO],
