# because the TranslatorFactory makes it superfluous.",context_required,context_required,True,1.0,forced_route:context_required,,0.0,0.0,0.0,0.0,pass,True,The function enable_lazy is marked for removal due to its redundancy with TranslatorFactory.,,The enable_lazy function that configures translation functions.,identified_methods=2; retrieved_methods=2,delete_or_remove,high,delete_block,Ensure that removal does not affect other parts of the code relying on lazy translation.,method_context,0,0,0,TranslatorFactory | _,TranslatorFactory | _,,2,"[{""method_name"": ""TranslatorFactory"", ""path"": ""manila/openstack/common/gettextutils.py"", ""class_name"": null, ""start_line"": 41, ""end_line"": 115, ""source"": ""class TranslatorFactory(object):
    """"""Create translator functions
    """"""

    def __init__(self, domain, lazy=False, localedir=None):
        """"""Establish a set of translation functions for the domain.

        :param domain: Name of translation domain,
                       specifying a message catalog.
        :type domain: str
        :param lazy: Delays translation until a message is emitted.
                     Defaults to False.
        :type lazy: Boolean
        :param localedir: Directory with translation catalogs.
        :type localedir: str
        """"""
        self.domain = domain
        self.lazy = lazy
        if localedir is None:
            localedir = os.environ.get(domain.upper() + '_LOCALEDIR')
        self.localedir = localedir

    def _make_translation_func(self, domain=None):
        """"""Return a new translation function ready for use.

        Takes into account whether or not lazy translation is being
        done.

        The domain can be specified to override the default from the
        factory, but the localedir from the factory is always used
        because we assume the log-level translation catalogs are
        installed in the same directory as the main application
        catalog.

        """"""
        if domain is None:
            domain = self.domain
        if self.lazy:
            return functools.partial(Message, domain=domain)
        t = gettext.translation(
            domain,
            localedir=self.localedir,
            fallback=True,
        )
        if six.PY3:
            return t.gettext
