    if len(data) < cur+2:
        raise BufferUnderflowError(""Not enough data left"")
    (strLen,) = struct.unpack('>h', data[cur:cur+2])
    if strLen == -1:
        return (None, cur+2)
    cur += 2
    if len(data) < cur+strLen:
        raise BufferUnderflowError(""Not enough data left"")
